mapper.select:
SELECT e.EMP_NO AS empNo, e.EMP_NM AS empNm, e.DEPT_CD AS deptCd, d.DEPT_NM AS deptNm, e.JBGD_CD AS jbgdCd, p.JBGD_NM AS jbgdNm, e.EMPL_SE_CD AS emplSeCd, e.EMP_STTS_CD AS empSttsCd, e.JNCMP_YMD AS jncmpYmd, e.RETIR_YMD AS retirYmd FROM hrm_emp_master e LEFT JOIN hrm_dept_master d ON e.DEPT_CD = d.DEPT_CD LEFT JOIN hrm_pos_master p ON e.JBGD_CD = p.JBGD_CD
AND e.EMP_NM LIKE CONCAT('%', #{empNm}, '%')
AND e.DEPT_CD = #{deptCd}
AND e.JBGD_CD = #{jbgdCd}
AND e.EMP_STTS_CD = #{empSttsCd}
ORDER BY e.JNCMP_YMD DESC, e.EMP_NO DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM hrm_emp_master e


        AND e.EMP_NM LIKE CONCAT('%', #{empNm}, '%')


        AND e.DEPT_CD = #{deptCd}


        AND e.JBGD_CD = #{jbgdCd}


        AND e.EMP_STTS_CD = #{empSttsCd}

mapper.update:
UPDATE hrm_emp_master
EMP_NM = #{empNm}, EMP_ENG_NM = #{empEngNm}, EML_ADDR = #{emlAddr}, DEPT_CD = #{deptCd}, JBGD_CD = #{jbgdCd}, EMPL_SE_CD = #{emplSeCd}, EMP_STTS_CD = #{empSttsCd}, JNCMP_YMD = #{jncmpYmd}, RETIR_YMD = #{retirYmd},
RSDNT_NO = #{rsdntNo},
BRDT = #{brdt}, SEXDSTN_CD = #{sexdstnCd}, MBTLNUM = #{mbtlnum}, ADDR = #{addr}, ZIP_CD = #{zipCd}, ADDR_DTL = #{addrDtl}, BANK_CD = #{bankCd}, ACTNO = #{actno}, EMRGNC_CNTCT_NM = #{emrgncCntctNm}, EMRGNC_TELNO = #{emrgncTelno}
WHERE EMP_NO = #{empNo}
